"use client";

import React, { useState } from "react";
import { ChevronDown, HelpCircle } from "lucide-react";

const FAQS = [
  {
    question: "How does NEXUS BI ensure AI insights are not hallucinated?",
    answer:
      "Every single metric and insight generated by NEXUS BI is backed by our certified Semantic Layer and embedded DuckDB queries. We enforce an unbroken chain of custody: clicking on any number opens the Evidence Drawer showing the exact SQL, formula, raw rows, sample distributions, and confidence interval.",
  },
  {
    question: "Can I connect my own custom datasets?",
    answer:
      "Yes. You can upload CSV or Excel files via the Data Hub or connect to DuckDB, PostgreSQL, Snowflake, or BigQuery. The system automatically profiles column types, checks 5 dimensions of data quality, and maps them to semantic metric definitions.",
  },
  {
    question: "What is the 5-Dimension Data Trust Score?",
    answer:
      "Before running statistical analyses or machine learning forecasts, datasets undergo rigorous evaluation across Completeness (null checks), Uniqueness (duplicate row/key detection), Validity (format and outlier limits), Consistency (referential integrity), and Freshness (timestamp drift).",
  },
  {
    question: "How are social and marketing metrics connected to financial data?",
    answer:
      "NEXUS BI joins social campaign metrics (spend, impressions, clicks, sentiment) with transactional sales tables via UTM campaign tags and chronological lag-correlation models. This immediately exposes vanity metric traps where campaigns look successful on surface impressions but yield negative return on ad spend (ROAS).",
  },
  {
    question: "Does NEXUS BI modify my raw data when applying 'Safe Fixes'?",
    answer:
      "Never destructively. Our Safe One-Click Fixes feature creates an explicit isolated preview showing before/after diffs, impacted row counts, and projected trust score recovery. Raw data remains immutable until you explicitly export or save a transformed version.",
  },
];

export function LandingFAQ() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  return (
    <section id="faq" className="py-24 md:py-32 bg-slate-950/40 border-t border-slate-800/80">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center space-y-4 mb-16">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-blue-950/60 border border-blue-800/60 text-xs font-mono text-blue-300 font-semibold">
            <span>GOVERNANCE &amp; ARCHITECTURE</span>
          </div>
          <h2 className="text-3xl sm:text-5xl font-extrabold tracking-tight text-white leading-tight">
            Clear Answers on <br />
            <span className="ai-gradient-text">Accuracy &amp; Data Trust.</span>
          </h2>
          <p className="text-base text-slate-300">
            Everything you need to know about how NEXUS BI guarantees statistical evidence.
          </p>
        </div>

        <div className="space-y-4">
          {FAQS.map((faq, idx) => {
            const isOpen = openIndex === idx;
            return (
              <div
                key={idx}
                className="rounded-2xl bg-slate-900/60 border border-slate-800 overflow-hidden transition-all duration-200"
              >
                <button
                  type="button"
                  onClick={() => setOpenIndex(isOpen ? null : idx)}
                  className="w-full px-6 py-5 flex items-center justify-between text-left text-white hover:text-blue-400 transition-colors"
                >
                  <span className="text-base font-semibold tracking-tight">{faq.question}</span>
                  <ChevronDown
                    className={`w-4 h-4 text-slate-400 shrink-0 transition-transform duration-200 ${
                      isOpen ? "rotate-180 text-blue-400" : ""
                    }`}
                  />
                </button>
                {isOpen && (
                  <div className="px-6 pb-5 text-sm text-slate-300 leading-relaxed border-t border-slate-800 pt-4 font-normal">
                    {faq.answer}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
